const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;

pub const DType = enum { f64 };

pub const Shape = []const usize;

pub fn totalElements(shape: Shape) usize {
    var total: usize = 1;
    for (shape) |dim| {
        total *= dim;
    }
    return total;
}

fn flatToMultiIndex(flat_idx: usize, shape: Shape, allocator: Allocator) ![]usize {
    var indices = try allocator.alloc(usize, shape.len);
    var remaining = flat_idx;
    var i: usize = shape.len;
    while (i > 0) {
        i -= 1;
        indices[i] = remaining % shape[i];
        remaining /= shape[i];
    }
    return indices;
}

fn multiToFlatIndex(indices: []const usize, strides: []const usize) usize {
    var idx: usize = 0;
    for (indices, 0..) |i, dim| {
        idx += i * strides[dim];
    }
    return idx;
}

pub const Complex = struct {
    real: f64,
    imag: f64,

    pub fn init(real: f64, imag: f64) Complex {
        return Complex{ .real = real, .imag = imag };
    }

    pub fn add(self: Complex, other: Complex) Complex {
        return Complex{ .real = self.real + other.real, .imag = self.imag + other.imag };
    }

    pub fn sub(self: Complex, other: Complex) Complex {
        return Complex{ .real = self.real - other.real, .imag = self.imag - other.imag };
    }

    pub fn mul(self: Complex, other: Complex) Complex {
        return Complex{
            .real = self.real * other.real - self.imag * other.imag,
            .imag = self.real * other.imag + self.imag * other.real,
        };
    }

    pub fn scale(self: Complex, s: f64) Complex {
        return Complex{ .real = self.real * s, .imag = self.imag * s };
    }

    pub fn magnitude(self: Complex) f64 {
        return @sqrt(self.real * self.real + self.imag * self.imag);
    }
};

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: Shape,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,
    requires_grad: bool = false,
    grad: ?*Tensor = null,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !Tensor {
        const total = totalElements(shape);
        const data = try allocator.alloc(f64, total);
        @memset(data, 0.0);
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .is_view = false,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
        if (self.grad) |g| {
            g.deinit();
            self.allocator.destroy(g);
        }
    }

    pub fn view(self: Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        if (totalElements(self.shape) != totalElements(new_shape)) {
            return error.ShapeMismatch;
        }
        const shape_copy = try allocator.dupe(usize, new_shape);
        var strides = try allocator.alloc(usize, new_shape.len);
        if (new_shape.len > 0) {
            strides[new_shape.len - 1] = 1;
            var i: usize = new_shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * new_shape[i];
            }
        }
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
            .requires_grad = self.requires_grad,
            .grad = self.grad,
        };
    }

    pub fn reshape(self: *Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        return self.view(allocator, new_shape);
    }

    pub fn get(self: *const Tensor, indices: []const usize) f64 {
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            idx += i * self.strides[dim];
        }
        return self.data[idx];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f64) void {
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            idx += i * self.strides[dim];
        }
        self.data[idx] = value;
    }

    fn incrementIndices(indices: []usize, shape: Shape, len: usize) bool {
        var i = len;
        while (i > 0) {
            i -= 1;
            indices[i] += 1;
            if (indices[i] < shape[i]) {
                return false;
            }
            indices[i] = 0;
        }
        return true;
    }

    pub fn add(self: *const Tensor, other: *const Tensor, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, other.shape) or !std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            const v1 = self.get(indices);
            const v2 = other.get(indices);
            result.set(indices, v1 + v2);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn mul(self: *const Tensor, other: *const Tensor, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, other.shape) or !std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            const v1 = self.get(indices);
            const v2 = other.get(indices);
            result.set(indices, v1 * v2);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0] or result.shape.len != 2 or result.shape[0] != self.shape[0] or result.shape[1] != other.shape[1]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = other.shape[1];
        const k = self.shape[1];
        @memset(result.data, 0.0);
        for (0..m) |i| {
            for (0..n) |j| {
                var dot_product: f64 = 0.0;
                for (0..k) |l| {
                    dot_product += self.data[self.offset + i * self.strides[0] + l * self.strides[1]] * other.data[other.offset + l * other.strides[0] + j * other.strides[1]];
                }
                result.data[result.offset + i * result.strides[0] + j * result.strides[1]] = dot_product;
            }
        }
    }

    pub fn transpose(self: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != 2 or result.shape.len != 2 or self.shape[0] != result.shape[1] or self.shape[1] != result.shape[0]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = self.shape[1];
        for (0..m) |i| {
            for (0..n) |j| {
                result.data[result.offset + j * result.strides[0] + i * result.strides[1]] = self.data[self.offset + i * self.strides[0] + j * self.strides[1]];
            }
        }
    }

    pub fn sum(self: *const Tensor, allocator: Allocator) !Tensor {
        var result = try Tensor.init(allocator, &.{1}, self.dtype);
        var total_sum: f64 = 0.0;
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            total_sum += self.get(indices);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        result.data[result.offset] = total_sum;
        return result;
    }

    pub fn mean(self: *const Tensor, allocator: Allocator) !Tensor {
        var sum_tensor = try self.sum(allocator);
        const total = @as(f64, @floatFromInt(totalElements(self.shape)));
        sum_tensor.data[sum_tensor.offset] /= total;
        return sum_tensor;
    }

    pub fn conv2d(self: *const Tensor, kernel: *const Tensor, padding: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 4 or kernel.shape.len != 4 or self.shape[1] != kernel.shape[1]) {
            return error.InvalidShapeForConv;
        }
        const batch = self.shape[0];
        const in_channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3];
        const out_channels = kernel.shape[0];
        const k_h = kernel.shape[2];
        const k_w = kernel.shape[3];
        const out_h = ((in_h + 2 * padding - k_h) / stride) + 1;
        const out_w = ((in_w + 2 * padding - k_w) / stride) + 1;
        const out_shape = &[_]usize{ batch, out_channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        for (0..batch) |b| {
            for (0..out_channels) |oc| {
                for (0..out_h) |oh| {
                    for (0..out_w) |ow| {
                        var sum_val: f64 = 0.0;
                        const start_h = @as(isize, @intCast(stride * oh)) - @as(isize, @intCast(padding));
                        const start_w = @as(isize, @intCast(stride * ow)) - @as(isize, @intCast(padding));
                        for (0..k_h) |kh| {
                            const ih = start_h + @as(isize, @intCast(kh));
                            if (ih < 0 or ih >= @as(isize, @intCast(in_h))) continue;
                            for (0..k_w) |kw| {
                                const iw = start_w + @as(isize, @intCast(kw));
                                if (iw < 0 or iw >= @as(isize, @intCast(in_w))) continue;
                                for (0..in_channels) |ic| {
                                    const self_idx = &[_]usize{ b, ic, @as(usize, @intCast(ih)), @as(usize, @intCast(iw)) };
                                    const kernel_idx = &[_]usize{ oc, ic, kh, kw };
                                    sum_val += self.get(self_idx) * kernel.get(kernel_idx);
                                }
                            }
                        }
                        const result_idx = &[_]usize{ b, oc, oh, ow };
                        result.set(result_idx, sum_val);
                    }
                }
            }
        }
        return result;
    }

    pub fn maxpool2d(self: *const Tensor, kernel_size: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 4) {
            return error.InvalidShapeForPool;
        }
        const batch = self.shape[0];
        const channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3];
        const out_h = (in_h - kernel_size) / stride + 1;
        const out_w = (in_w - kernel_size) / stride + 1;
        const out_shape = &[_]usize{ batch, channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        for (0..batch) |b| {
            for (0..channels) |c| {
                for (0..out_h) |oh| {
                    for (0..out_w) |ow| {
                        var max_val: f64 = -math.inf(f64);
                        for (0..kernel_size) |kh| {
                            const ih = stride * oh + kh;
                            if (ih >= in_h) break;
                            for (0..kernel_size) |kw| {
                                const iw = stride * ow + kw;
                                if (iw >= in_w) break;
                                const idx = &[_]usize{ b, c, ih, iw };
                                const val = self.get(idx);
                                if (val > max_val) max_val = val;
                            }
                        }
                        const result_idx = &[_]usize{ b, c, oh, ow };
                        result.set(result_idx, max_val);
                    }
                }
            }
        }
        return result;
    }

    pub fn relu(self: *const Tensor, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            const val = self.get(indices);
            result.set(indices, if (val > 0.0) val else 0.0);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn softmax(self: *const Tensor, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        var max_val: f64 = -math.inf(f64);
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            const val = self.get(indices);
            if (val > max_val) max_val = val;
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        var sum_exp: f64 = 0.0;
        @memset(indices, 0);
        done = false;
        while (!done) {
            const val = self.get(indices);
            sum_exp += @exp(val - max_val);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        @memset(indices, 0);
        done = false;
        while (!done) {
            const val = self.get(indices);
            result.set(indices, @exp(val - max_val) / sum_exp);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn backward(self: *Tensor, grad_output: *const Tensor) !void {
        if (!self.requires_grad) return;
        if (self.grad == null) {
            const new_grad = try self.allocator.create(Tensor);
            new_grad.* = try Tensor.init(self.allocator, self.shape, self.dtype);
            self.grad = new_grad;
        }
        if (self.grad) |g| {
            try grad_output.add(g, g, self.allocator);
        }
    }

    pub fn zero_grad(self: *Tensor) void {
        if (self.grad) |g| {
            @memset(g.data, 0.0);
        }
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var cloned = try Tensor.init(allocator, self.shape, self.dtype);
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            cloned.set(indices, self.get(indices));
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        cloned.offset = 0;
        cloned.requires_grad = self.requires_grad;
        return cloned;
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        const magic: u32 = 0x5A494754;
        try writer.writeInt(u32, magic, .little);
        const version: u32 = 1;
        try writer.writeInt(u32, version, .little);
        const ndim = @as(u32, @intCast(self.shape.len));
        try writer.writeInt(u32, ndim, .little);
        for (self.shape) |dim| {
            const dim_u64 = @as(u64, @intCast(dim));
            try writer.writeInt(u64, dim_u64, .little);
        }
        const len = self.shape.len;
        var indices = try self.allocator.alloc(usize, len);
        defer self.allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            const val = self.get(indices);
            const bytes = std.mem.asBytes(&val);
            try writer.writeAll(bytes);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn load(allocator: Allocator, path: []const u8, dtype: DType) !Tensor {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const reader = file.reader();
        const magic = try reader.readInt(u32, .little);
        if (magic != 0x5A494754) return error.InvalidMagic;
        const version = try reader.readInt(u32, .little);
        if (version != 1) return error.UnsupportedVersion;
        const ndim = try reader.readInt(u32, .little);
        var shape_buf = try allocator.alloc(usize, ndim);
        for (0..ndim) |i| {
            const dim_u64 = try reader.readInt(u64, .little);
            shape_buf[i] = @as(usize, @intCast(dim_u64));
        }
        const total = totalElements(shape_buf);
        const data = try allocator.alloc(f64, total);
        errdefer allocator.free(data);
        for (0..total) |i| {
            const bytes = std.mem.asBytes(&data[i]);
            const read_count = try reader.readAll(bytes);
            if (read_count != @sizeOf(f64)) {
                allocator.free(data);
                allocator.free(shape_buf);
                return error.IncompleteRead;
            }
        }
        var strides = try allocator.alloc(usize, ndim);
        if (ndim > 0) {
            strides[ndim - 1] = 1;
            var i: usize = ndim;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape_buf[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_buf,
            .strides = strides,
            .dtype = dtype,
        };
    }

    pub fn adam_update(self: *Tensor, m: *Tensor, v: *Tensor, beta1: f64, beta2: f64, lr: f64, t: usize, eps: f64, allocator: Allocator) !void {
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        while (!done) {
            const grad_val = if (self.grad) |g| g.get(indices) else 0.0;
            const m_old = m.get(indices);
            const v_old = v.get(indices);
            const m_new = beta1 * m_old + (1.0 - beta1) * grad_val;
            const v_new = beta2 * v_old + (1.0 - beta2) * grad_val * grad_val;
            m.set(indices, m_new);
            v.set(indices, v_new);
            const m_hat = m_new / (1.0 - math.pow(f64, beta1, @floatFromInt(t)));
            const v_hat = v_new / (1.0 - math.pow(f64, beta2, @floatFromInt(t)));
            const update = -lr * m_hat / (@sqrt(v_hat) + eps);
            const old_val = self.get(indices);
            self.set(indices, old_val + update);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn spectral_norm(self: *const Tensor, allocator: Allocator, num_power_iters: usize) !f64 {
        if (self.shape.len != 2) return error.InvalidShape;
        const m = self.shape[0];
        const n = self.shape[1];
        var u = try Tensor.init(allocator, &.{m}, .f64);
        defer u.deinit();
        var v = try Tensor.init(allocator, &.{n}, .f64);
        defer v.deinit();
        var prng = std.rand.DefaultPrng.init(42);
        const rand = prng.random();
        for (0..m) |i| {
            u.data[i] = rand.float(f64) * 2.0 - 1.0;
        }
        var u_norm: f64 = 0.0;
        for (0..m) |i| {
            u_norm += u.data[i] * u.data[i];
        }
        u_norm = @sqrt(u_norm);
        for (0..m) |i| {
            u.data[i] /= u_norm;
        }
        for (0..num_power_iters) |_| {
            @memset(v.data, 0.0);
            for (0..n) |j| {
                for (0..m) |i| {
                    v.data[j] += self.get(&.{ i, j }) * u.data[i];
                }
            }
            var v_norm: f64 = 0.0;
            for (0..n) |j| {
                v_norm += v.data[j] * v.data[j];
            }
            v_norm = @sqrt(v_norm);
            if (v_norm > 1e-12) {
                for (0..n) |j| {
                    v.data[j] /= v_norm;
                }
            }
            @memset(u.data, 0.0);
            for (0..m) |i| {
                for (0..n) |j| {
                    u.data[i] += self.get(&.{ i, j }) * v.data[j];
                }
            }
            u_norm = 0.0;
            for (0..m) |i| {
                u_norm += u.data[i] * u.data[i];
            }
            u_norm = @sqrt(u_norm);
            if (u_norm > 1e-12) {
                for (0..m) |i| {
                    u.data[i] /= u_norm;
                }
            }
        }
        var sigma: f64 = 0.0;
        for (0..m) |i| {
            for (0..n) |j| {
                sigma += u.data[i] * self.get(&.{ i, j }) * v.data[j];
            }
        }
        return sigma;
    }

    pub fn dropout(self: *const Tensor, p: f64, seed: u64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        const scale = 1.0 / (1.0 - p);
        while (!done) {
            const val = self.get(indices);
            const drop = rand.float(f64);
            if (drop < p) {
                result.set(indices, 0.0);
            } else {
                result.set(indices, val * scale);
            }
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn layer_norm(self: *const Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape) or !std.mem.eql(usize, self.shape, gamma.shape) or !std.mem.eql(usize, self.shape, beta.shape)) {
            return error.ShapeMismatch;
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        var mean_val: f64 = 0.0;
        @memset(indices, 0);
        var done = false;
        while (!done) {
            mean_val += self.get(indices);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        mean_val /= @as(f64, @floatFromInt(totalElements(self.shape)));
        var var_sum: f64 = 0.0;
        @memset(indices, 0);
        done = false;
        while (!done) {
            const val = self.get(indices);
            var_sum += (val - mean_val) * (val - mean_val);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        const variance = var_sum / @as(f64, @floatFromInt(totalElements(self.shape)));
        const std_dev = @sqrt(variance + eps);
        @memset(indices, 0);
        done = false;
        while (!done) {
            const val = self.get(indices);
            const normalized = (val - mean_val) / std_dev;
            const gamma_val = gamma.get(indices);
            const beta_val = beta.get(indices);
            result.set(indices, gamma_val * normalized + beta_val);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn gelu(self: *const Tensor, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var done = false;
        const sqrt_2_over_pi: f64 = 0.7978845608028654;
        const coeff: f64 = 0.044715;
        while (!done) {
            const x = self.get(indices);
            const tanh_arg = sqrt_2_over_pi * (x + coeff * x * x * x);
            const exp_pos = @exp(tanh_arg);
            const exp_neg = @exp(-tanh_arg);
            const tanh_val = (exp_pos - exp_neg) / (exp_pos + exp_neg);
            result.set(indices, 0.5 * x * (1.0 + tanh_val));
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn batch_norm(self: *const Tensor, running_mean: *Tensor, running_var: *Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, training: bool, momentum: f64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape) or self.shape.len < 2) {
            return error.ShapeMismatch;
        }
        const batch_size = self.shape[0];
        const channels = self.shape[1];
        var spatial: usize = 1;
        for (2..self.shape.len) |dim| {
            spatial *= self.shape[dim];
        }
        var means = try allocator.alloc(f64, channels);
        defer allocator.free(means);
        @memset(means, 0.0);
        var variances = try allocator.alloc(f64, channels);
        defer allocator.free(variances);
        @memset(variances, 0.0);
        if (training) {
            for (0..channels) |c| {
                var channel_sum: f64 = 0.0;
                for (0..batch_size) |b| {
                    for (0..spatial) |s| {
                        const idx = &[_]usize{ b, c } ++ std.mem.sliceTo(&[_]usize{0} ** (self.shape.len - 2), 0) ++ &[_]usize{s};
                        channel_sum += self.get(idx[0..self.shape.len]);
                    }
                }
                means[c] = channel_sum / @as(f64, @floatFromInt(batch_size * spatial));
            }
            for (0..channels) |c| {
                var var_sum: f64 = 0.0;
                for (0..batch_size) |b| {
                    for (0..spatial) |s| {
                        const idx = &[_]usize{ b, c } ++ std.mem.sliceTo(&[_]usize{0} ** (self.shape.len - 2), 0) ++ &[_]usize{s};
                        const val = self.get(idx[0..self.shape.len]);
                        var_sum += (val - means[c]) * (val - means[c]);
                    }
                }
                variances[c] = var_sum / @as(f64, @floatFromInt(batch_size * spatial));
            }
            for (0..channels) |c| {
                const run_mean_idx = &[_]usize{c};
                const run_var_idx = &[_]usize{c};
                const run_mean_old = running_mean.get(run_mean_idx);
                const run_var_old = running_var.get(run_var_idx);
                running_mean.set(run_mean_idx, momentum * run_mean_old + (1.0 - momentum) * means[c]);
                running_var.set(run_var_idx, momentum * run_var_old + (1.0 - momentum) * variances[c]);
            }
        } else {
            for (0..channels) |c| {
                means[c] = running_mean.get(&[_]usize{c});
                variances[c] = running_var.get(&[_]usize{c});
            }
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        for (0..batch_size) |b| {
            indices[0] = b;
            for (0..channels) |c| {
                indices[1] = c;
                for (0..spatial) |s| {
                    for (2..len) |dim| {
                        indices[dim] = 0;
                    }
                    indices[len - 1] = s;
                    const val = self.get(indices);
                    const normalized = (val - means[c]) / @sqrt(variances[c] + eps);
                    const gamma_val = gamma.get(&[_]usize{c});
                    const beta_val = beta.get(&[_]usize{c});
                    result.set(indices, gamma_val * normalized + beta_val);
                }
            }
        }
    }

    pub fn embedding(self: *const Tensor, indices: *const Tensor, allocator: Allocator) !Tensor {
        if (indices.shape.len != 1 or self.shape.len != 2) {
            return error.InvalidShape;
        }
        const vocab_size = self.shape[0];
        const embed_dim = self.shape[1];
        var result = try Tensor.init(allocator, &.{ indices.shape[0], embed_dim }, .f64);
        for (0..indices.shape[0]) |i| {
            const idx_val = @as(usize, @intFromFloat(indices.data[indices.offset + i]));
            if (idx_val >= vocab_size) {
                return error.IndexOutOfBounds;
            }
            for (0..embed_dim) |d| {
                const embed_idx = &[_]usize{ idx_val, d };
                const val = self.get(embed_idx);
                result.set(&[_]usize{ i, d }, val);
            }
        }
        return result;
    }

    pub fn positional_encoding(max_len: usize, d_model: usize, allocator: Allocator) !Tensor {
        var pe = try Tensor.init(allocator, &.{ max_len, d_model }, .f64);
        for (0..max_len) |pos| {
            const pos_f = @as(f64, @floatFromInt(pos));
            for (0..d_model) |i| {
                const i_f = @as(f64, @floatFromInt(i));
