        while (!done) {
            const val = self.get(indices);
            sum_exp += @exp(val - max_val);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        std.mem.set(usize, indices, 0);
        done = false;
        while (!done) {
            const val = self.get(indices);
            result.set(indices, @exp(val - max_val) / sum_exp);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn backward(self: *Tensor, grad_output: *const Tensor) !void {
        if (!self.requires_grad) return;
        if (self.grad == null) {
            const new_grad = try self.allocator.create(Tensor);
            new_grad.* = try Tensor.init(self.allocator, self.shape, self.dtype);
            self.grad = new_grad;
        }
        if (self.grad) |g| {
            try grad_output.add(g, g, self.allocator);
        }
    }

    pub fn zero_grad(self: *Tensor) void {
        if (self.grad) |g| {
            std.mem.set(f64, g.data, 0.0);
        }
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var cloned = try Tensor.init(allocator, self.shape, self.dtype);
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        std.mem.set(usize, indices, 0);
        var done = false;
        while (!done) {
            cloned.set(indices, self.get(indices));
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        cloned.offset = 0;
        cloned.requires_grad = self.requires_grad;
        return cloned;
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        const magic: u32 = 0x5A494754;
        try writer.writeInt(u32, magic, .little);
        const version: u32 = 1;
        try writer.writeInt(u32, version, .little);
        const ndim = @as(u32, @intCast(self.shape.len));
        try writer.writeInt(u32, ndim, .little);
        for (self.shape) |dim| {
            const dim_u64 = @as(u64, @intCast(dim));
            try writer.writeInt(u64, dim_u64, .little);
        }
        const len = self.shape.len;
        var indices = try self.allocator.alloc(usize, len);
        defer self.allocator.free(indices);
        std.mem.set(usize, indices, 0);
        var done = false;
        while (!done) {
            const val = self.get(indices);
            const bytes = std.mem.asBytes(&val);
            try writer.writeAll(bytes);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn load(allocator: Allocator, path: []const u8, dtype: DType) !Tensor {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const reader = file.reader();
        const magic = try reader.readInt(u32, .little);
        if (magic != 0x5A494754) return error.InvalidMagic;
        const version = try reader.readInt(u32, .little);
        if (version != 1) return error.UnsupportedVersion;
        const ndim = try reader.readInt(u32, .little);
        var shape_buf = try allocator.alloc(usize, ndim);
        for (0..ndim) |i| {
            const dim_u64 = try reader.readInt(u64, .little);
            shape_buf[i] = @as(usize, @intCast(dim_u64));
        }
        const total = totalElements(shape_buf);
        const data = try allocator.alloc(f64, total);
        errdefer allocator.free(data);
        for (0..total) |i| {
            const bytes = std.mem.asBytes(&data[i]);
            try reader.readNoEof(bytes);
        }
        var strides = try allocator.alloc(usize, ndim);
        if (ndim > 0) {
            strides[ndim - 1] = 1;
            var i: usize = ndim;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape_buf[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_buf,
            .strides = strides,
            .dtype = dtype,
        };
    }

    pub fn adam_update(self: *Tensor, m: *Tensor, v: *Tensor, beta1: f64, beta2: f64, lr: f64, t: usize, eps: f64, allocator: Allocator) !void {
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        std.mem.set(usize, indices, 0);
        var done = false;
        while (!done) {
            const grad_val = if (self.grad) |g| g.get(indices) else 0.0;
            const m_old = m.get(indices);
            const v_old = v.get(indices);
            const m_new = beta1 * m_old + (1.0 - beta1) * grad_val;
            const v_new = beta2 * v_old + (1.0 - beta2) * grad_val * grad_val;
            m.set(indices, m_new);
            v.set(indices, v_new);
            const m_hat = m_new / (1.0 - math.pow(f64, beta1, @floatFromInt(t)));
            const v_hat = v_new / (1.0 - math.pow(f64, beta2, @floatFromInt(t)));
            const update = -lr * m_hat / (@sqrt(v_hat) + eps);
            const old_val = self.get(indices);
            self.set(indices, old_val + update);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn spectral_norm(self: *const Tensor, allocator: Allocator, num_power_iters: usize) !f64 {
        if (self.shape.len != 2) return error.InvalidShape;
        const m = self.shape[0];
        const n = self.shape[1];
        var u = try Tensor.init(allocator, &.{m}, .f64);
        defer u.deinit();
        var v = try Tensor.init(allocator, &.{n}, .f64);
        defer v.deinit();
        var prng = std.rand.DefaultPrng.init(42);
        const rand = prng.random();
        for (0..m) |i| {
            u.data[i] = rand.float(f64) * 2.0 - 1.0;
        }
        var u_norm: f64 = 0.0;
        for (0..m) |i| {
            u_norm += u.data[i] * u.data[i];
        }
        u_norm = @sqrt(u_norm);
        for (0..m) |i| {
            u.data[i] /= u_norm;
        }
        for (0..num_power_iters) |_| {
            std.mem.set(f64, v.data, 0.0);
            for (0..n) |j| {
                for (0..m) |i| {
                    v.data[j] += self.get(&.{ i, j }) * u.data[i];
                }
            }
            var v_norm: f64 = 0.0;
            for (0..n) |j| {
                v_norm += v.data[j] * v.data[j];
            }
            v_norm = @sqrt(v_norm);
            if (v_norm > 1e-12) {
                for (0..n) |j| {
                    v.data[j] /= v_norm;
                }
            }
            std.mem.set(f64, u.data, 0.0);
            for (0..m) |i| {
                for (0..n) |j| {
                    u.data[i] += self.get(&.{ i, j }) * v.data[j];
                }
            }
            u_norm = 0.0;
            for (0..m) |i| {
                u_norm += u.data[i] * u.data[i];
            }
            u_norm = @sqrt(u_norm);
            if (u_norm > 1e-12) {
                for (0..m) |i| {
                    u.data[i] /= u_norm;
                }
            }
        }
        var sigma: f64 = 0.0;
        for (0..m) |i| {
            for (0..n) |j| {
                sigma += u.data[i] * self.get(&.{ i, j }) * v.data[j];
            }
        }
        return sigma;
    }

    pub fn dropout(self: *const Tensor, p: f64, seed: u64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        std.mem.set(usize, indices, 0);
        var done = false;
        const scale = 1.0 / (1.0 - p);
        while (!done) {
            const val = self.get(indices);
            const drop = rand.float(f64);
            if (drop < p) {
                result.set(indices, 0.0);
            } else {
                result.set(indices, val * scale);
            }
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn layer_norm(self: *const Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape) or !std.mem.eql(usize, self.shape, gamma.shape) or !std.mem.eql(usize, self.shape, beta.shape)) {
            return error.ShapeMismatch;
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        var mean_val: f64 = 0.0;
        std.mem.set(usize, indices, 0);
        var done = false;
        while (!done) {
            mean_val += self.get(indices);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        mean_val /= @as(f64, @floatFromInt(totalElements(self.shape)));
        var var_sum: f64 = 0.0;
        std.mem.set(usize, indices, 0);
        done = false;
        while (!done) {
            const val = self.get(indices);
            var_sum += (val - mean_val) * (val - mean_val);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
        const variance = var_sum / @as(f64, @floatFromInt(totalElements(self.shape)));
        const std_dev = @sqrt(variance + eps);
        std.mem.set(usize, indices, 0);
        done = false;
        while (!done) {
            const val = self.get(indices);
            const normalized = (val - mean_val) / std_dev;
            const gamma_val = gamma.get(indices);
            const beta_val = beta.get(indices);
            result.set(indices, gamma_val * normalized + beta_val);
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn gelu(self: *const Tensor, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const len = self.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        std.mem.set(usize, indices, 0);
        var done = false;
        const sqrt_2_over_pi: f64 = 0.7978845608028654;
        const coeff: f64 = 0.044715;
        while (!done) {
            const x = self.get(indices);
            const tanh_arg = sqrt_2_over_pi * (x + coeff * x * x * x);
            const exp_pos = @exp(tanh_arg);
            const exp_neg = @exp(-tanh_arg);
            const tanh_val = (exp_pos - exp_neg) / (exp_pos + exp_neg);
            result.set(indices, 0.5 * x * (1.0 + tanh_val));
            done = Tensor.incrementIndices(indices, self.shape, len);
        }
    }

    pub fn batch_norm(self: *const Tensor, running_mean: *Tensor, running_var: *Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, training: bool, momentum: f64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape) or self.shape.len < 2) {
            return error.ShapeMismatch;
        }
        const channels = self.shape[1];
        if (running_mean.shape.len != 1 or running_var.shape.len != 1 or running_mean.shape[0] != channels or running_var.shape[0] != channels) {
            return error.ShapeMismatch;
        }
        if (gamma.shape.len != 1 or beta.shape.len != 1 or gamma.shape[0] != channels or beta.shape[0] != channels) {
            return error.ShapeMismatch;
        }
        var count_per_c: usize = self.shape[0];
        var d: usize = 2;
        while (d < self.shape.len) : (d += 1) {
            count_per_c *= self.shape[d];
        }
        var means = try allocator.alloc(f64, channels);
        defer allocator.free(means);
        std.mem.set(f64, means, 0.0);
        var variances = try allocator.alloc(f64, channels);
        defer allocator.free(variances);
        std.mem.set(f64, variances, 0.0);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        std.mem.set(usize, indices, 0);
        var done = false;
        while (!done) {
            const c = indices[1];
            means[c] += self.get(indices);
            done = Tensor.incrementIndices(indices, self.shape, self.shape.len);
        }
        for (0..channels) |c| {
            means[c] /= @as(f64, @floatFromInt(count_per_c));
        }
        std.mem.set(usize, indices, 0);
        done = false;
        while (!done) {
            const c = indices[1];
            const val = self.get(indices);
            const diff = val - means[c];
            variances[c] += diff * diff;
            done = Tensor.incrementIndices(indices, self.shape, self.shape.len);
        }
        for (0..channels) |c| {
            variances[c] /= @as(f64, @floatFromInt(count_per_c));
        }
        if (training) {
            for (0..channels) |c| {
                const old_m = running_mean.get(&[_]usize{c});
                const old_v = running_var.get(&[_]usize{c});
                running_mean.set(&[_]usize{c}, momentum * old_m + (1.0 - momentum) * means[c]);
                running_var.set(&[_]usize{c}, momentum * old_v + (1.0 - momentum) * variances[c]);
            }
        } else {
            for (0..channels) |c| {
                means[c] = running_mean.get(&[_]usize{c});
                variances[c] = running_var.get(&[_]usize{c});
            }
        }
        std.mem.set(usize, indices, 0);
        done = false;
        while (!done) {
            const c = indices[1];
            const val = self.get(indices);
            const norm = (val - means[c]) / @sqrt(variances[c] + eps);
            const g = gamma.get(&[_]usize{c});
            const b = beta.get(&[_]usize{c});
            result.set(indices, g * norm + b);
            done = Tensor.incrementIndices(indices, self.shape, self.shape.len);
        }
    }

    pub fn embedding(self: *const Tensor, indices: *const Tensor, allocator: Allocator) !Tensor {
        if (indices.shape.len != 1 or self.shape.len != 2) {
            return error.InvalidShape;
        }
        const vocab_size = self.shape[0];
        const embed_dim = self.shape[1];
        var result = try Tensor.init(allocator, &.{ indices.shape[0], embed_dim }, .f64);
        for (0..indices.shape[0]) |i| {
            const idx_val = @as(usize, @intFromFloat(indices.data[indices.offset + i]));
            if (idx_val >= vocab_size) {
                return error.IndexOutOfBounds;
            }
            for (0..embed_dim) |d| {
                const embed_idx = &[_]usize{ idx_val, d };
                const val = self.get(embed_idx);
                result.set(&[_]usize{ i, d }, val);
            }
        }
        return result;
    }

    pub fn positional_encoding(max_len: usize, d_model: usize, allocator: Allocator) !Tensor {
        var pe = try Tensor.init(allocator, &.{ max_len, d_model }, .f64);
        for (0..max_len) |pos| {
            const pos_f = @as(f64, @floatFromInt(pos));
            for (0..d_model) |i| {
                const i_f = @as(f64, @floatFromInt(i));
                const div_term = math.pow(f64, 10000.0, (2.0 * @floor(i_f / 2.0)) / @as(f64, @floatFromInt(d_model)));
                const angle = pos_f / div_term;
                if (i % 2 == 0) {
                    pe.set(&[_]usize{ pos, i }, @sin(angle));
                } else {
                    pe.set(&[_]usize{ pos, i }, @cos(angle));
                }
            }
        }
        return pe;
    }

    pub fn sparse_matmul(self: *const Tensor, other: *const Tensor, sparsity: f64, seed: u64, allocator: Allocator) !Tensor {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0]) {
            return error.ShapeMismatch;
        }
        var dense_result = try Tensor.init(allocator, &.{ self.shape[0], other.shape[1] }, .f64);
        defer dense_result.deinit();
        try self.matmul(other, &dense_result);
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        var sparse_result = try Tensor.init(allocator, dense_result.shape, .f64);
        const len = dense_result.shape.len;
        var indices = try allocator.alloc(usize, len);
        defer allocator.free(indices);
        std.mem.set(usize, indices, 0);
        var done = false;
        while (!done) {
            const keep = rand.float(f64) > sparsity;
            if (keep) {
                sparse_result.set(indices, dense_result.get(indices));
            } else {
                sparse_result.set(indices, 0.0);
            }
            done = Tensor.incrementIndices(indices, dense_result.shape, len);
        }
        return sparse_result;
    }

    pub fn fft(input: []const Complex, output: []Complex, allocator: Allocator) !void {
        const n = input.len;
        if (n != output.len) return error.LengthMismatch;
        if (n <= 1) {
            std.mem.copyForwards(Complex, output, input);
            return;
        }
        if (n & (n - 1) != 0) return error.NotPowerOfTwo;
        const half = n / 2;
        var even = try allocator.alloc(Complex, half);
        defer allocator.free(even);
        var odd = try allocator.alloc(Complex, half);
        defer allocator.free(odd);
        for (0..half) |i| {
            even[i] = input[2 * i];
            odd[i] = input[2 * i + 1];
        }
        const even_fft = try allocator.alloc(Complex, half);
        defer allocator.free(even_fft);
        const odd_fft = try allocator.alloc(Complex, half);
        defer allocator.free(odd_fft);
        try Tensor.fft(even, even_fft, allocator);
        try Tensor.fft(odd, odd_fft, allocator);
        for (0..half) |k| {
            const angle = -2.0 * math.pi * @as(f64, @floatFromInt(k)) / @as(f64, @floatFromInt(n));
            const twiddle = Complex.init(@cos(angle), @sin(angle));
            const t = twiddle.mul(odd_fft[k]);
            output[k] = even_fft[k].add(t);
            output[k + half] = even_fft[k].sub(t);
        }
    }

    pub fn ifft(input: []const Complex, output: []Complex, allocator: Allocator) !void {
        const n = input.len;
        if (n != output.len) return error.LengthMismatch;
        const conjugated = try allocator.alloc(Complex, n);
        defer allocator.free(conjugated);
        for (0..n) |i| {
            conjugated[i] = Complex.init(input[i].real, -input[i].imag);
        }
        const fft_result = try allocator.alloc(Complex, n);
        defer allocator.free(fft_result);
        try Tensor.fft(conjugated, fft_result, allocator);
        const n_f = @as(f64, @floatFromInt(n));
        for (0..n) |i| {
            output[i] = Complex.init(fft_result[i].real / n_f, -fft_result[i].imag / n_f);
        }
    }

    pub fn hadamard_transform(input: []const f64, output: []f64) !void {
        const n = input.len;
        if (n != output.len) return error.LengthMismatch;
        if (n & (n - 1) != 0) return error.NotPowerOfTwo;
        std.mem.copyForwards(f64, output, input);
        var h: usize = 1;
        while (h < n) : (h *= 2) {
            var i: usize = 0;
            while (i < n) : (i += h * 2) {
                for (0..h) |j| {
                    const idx1 = i + j;
                    const idx2 = i + j + h;
                    const a = output[idx1];
                    const b = output[idx2];
                    output[idx1] = a + b;
                    output[idx2] = a - b;
                }
            }
        }
        const norm = @sqrt(@as(f64, @floatFromInt(n)));
        for (0..n) |k| {
            output[k] /= norm;
        }
    }

    pub fn bspline_basis(t: f64, i: usize, k: usize, knots: []const f64, allocator: Allocator) !f64 {
        _ = allocator;
        if (k == 0) {
            if (i >= knots.len - 1) return 0.0;
            return if (t >= knots[i] and t < knots[i + 1]) 1.0 else 0.0;
        }
        var left: f64 = 0.0;
        var right: f64 = 0.0;
        if (i + k < knots.len) {
            const denom_left = knots[i + k] - knots[i];
            if (@abs(denom_left) > 1e-10) {
                const basis_left = try Tensor.bspline_basis(t, i, k - 1, knots, allocator);
                left = (t - knots[i]) / denom_left * basis_left;
            }
        }
        if (i + k + 1 < knots.len and i + 1 < knots.len) {
            const denom_right = knots[i + k + 1] - knots[i + 1];
            if (@abs(denom_right) > 1e-10) {
                const basis_right = try Tensor.bspline_basis(t, i + 1, k - 1, knots, allocator);
                right = (knots[i + k + 1] - t) / denom_right * basis_right;
            }
        }
        return left + right;
    }

    pub fn lorenz_attractor(x0: f64, y0: f64, z0: f64, sigma: f64, rho: f64, beta: f64, dt: f64, steps: usize, allocator: Allocator) !Tensor {
        var trajectory = try Tensor.init(allocator, &.{ steps, 3 }, .f64);
        var x = x0;
        var y = y0;
        var z = z0;
        for (0..steps) |step| {
            trajectory.set(&.{ step, 0 }, x);
            trajectory.set(&.{ step, 1 }, y);
            trajectory.set(&.{ step, 2 }, z);
            const dx = sigma * (y - x);
            const dy = x * (rho - z) - y;
            const dz = x * y - beta * z;
            x += dx * dt;
            y += dy * dt;
            z += dz * dt;
        }
        return trajectory;
    }

    pub fn s4d_ssm(input: *const Tensor, A: *const Tensor, B: *const Tensor, C: *const Tensor, D: *const Tensor, dt: f64, allocator: Allocator) !Tensor {
        if (input.shape.len != 2) return error.InvalidShape;
        const seq_len = input.shape[0];
        const input_dim = input.shape[1];
        if (A.shape.len != 1 or B.shape.len != 1 or C.shape.len != 1 or D.shape.len != 2) {
            return error.InvalidShape;
        }
        const state_dim = A.shape[0];
        if (B.shape[0] != state_dim or C.shape[0] != state_dim or D.shape[0] != input_dim or D.shape[1] != input_dim) {
            return error.ShapeMismatch;
        }
        var output = try Tensor.init(allocator, input.shape, .f64);
        var state = try Tensor.init(allocator, &.{state_dim}, .f64);
        defer state.deinit();
        var prev = try allocator.alloc(f64, state_dim);
        defer allocator.free(prev);
        for (0..seq_len) |t| {
            for (0..state_dim) |s| {
                prev[s] = state.data[state.offset + s];
            }
            for (0..state_dim) |s| {
                const a_val = A.data[A.offset + s];
                const b_val = B.data[B.offset + s];
                var input_contrib: f64 = 0.0;
                for (0..input_dim) |d| {
                    input_contrib += input.get(&.{ t, d }) * b_val;
                }
                const disc_a = @exp(a_val * dt);
                const gain = if (@abs(a_val) > 1e-12) (1.0 - disc_a) / a_val else dt;
                state.data[state.offset + s] = disc_a * prev[s] + gain * input_contrib;
            }
            for (0..input_dim) |d| {
                var out_val: f64 = 0.0;
                for (0..state_dim) |s| {
                    const c_val = C.data[C.offset + s];
                    out_val += c_val * state.data[state.offset + s];
                }
                const d_val = D.get(&.{ d, d });
                out_val += d_val * input.get(&.{ t, d });
                output.set(&.{ t, d }, out_val);
            }
        }
        return output;
    }

    pub fn hyena_conv(input: *const Tensor, short_filter: *const Tensor, long_filter: *const Tensor, allocator: Allocator) !Tensor {
        if (input.shape.len != 2 or short_filter.shape.len != 1 or long_filter.shape.len != 1) {
            return error.InvalidShape;
        }
        const seq_len = input.shape[0];
        const channels = input.shape[1];
        const short_len = short_filter.shape[0];
        const long_len = long_filter.shape[0];
        var short_conv = try Tensor.init(allocator, input.shape, .f64);
        defer short_conv.deinit();
        for (0..seq_len) |t| {
            for (0..channels) |c| {
                var conv_sum: f64 = 0.0;
                for (0..short_len) |k| {
                    if (t >= k) {
                        const idx = t - k;
                        conv_sum += input.get(&.{ idx, c }) * short_filter.data[short_filter.offset + k];
                    }
                }
                short_conv.set(&.{ t, c }, conv_sum);
            }
        }
        var output = try Tensor.init(allocator, input.shape, .f64);
        for (0..seq_len) |t| {
            for (0..channels) |c| {
                var conv_sum: f64 = 0.0;
                for (0..long_len) |k| {
                    if (t >= k) {
                        const idx = t - k;
                        conv_sum += short_conv.get(&.{ idx, c }) * long_filter.data[long_filter.offset + k];
                    }
                }
                output.set(&.{ t, c }, conv_sum);
            }
        }
        return output;
    }
